<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Backup / Restore"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php if(isset($_GET['download'])){$bundle=[];foreach(['posts.json','promo_codes.json','categories.json','site_settings.json','homepage.json','seo_settings.json','notifications.json'] as $f)$bundle[$f]=admin_data($f,[]);$bundle['games.json']=read_json(SITE_ROOT.'/data/games.json',[]);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="yonolootzone-admin-backup-'.date('Y-m-d').'.json"');echo json_encode($bundle,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$raw=file_get_contents($_FILES['backup']['tmp_name']??'');$b=json_decode($raw,true);if(is_array($b)){foreach(['posts.json','promo_codes.json','categories.json','site_settings.json','homepage.json','seo_settings.json','notifications.json'] as $f)if(array_key_exists($f,$b))admin_save($f,$b[$f]);if(isset($b['games.json']))write_json(SITE_ROOT.'/data/games.json',$b['games.json']);flash('success','Backup restored.');redirect_admin('backup.php');}}?><div class="row"><div class="col-md-6"><div class="card"><div class="card-body"><h3>Download Backup</h3><p>Games, posts, promo codes, categories and settings.</p><a href="backup.php?download=1" class="btn btn-pink">Download JSON Backup</a></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><h3>Restore Backup</h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="file" name="backup" accept=".json" required class="form-control-file mb-3"><button class="btn btn-outline-danger">Restore</button></form></div></div></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>